import { type Post } from '#site/content';

function getSlug(post: Post) {
  return post.path.split('posts/').at(-1);
}

function getPublishedPosts(posts: Post[]) {
  return posts.filter((post) => !post.draft);
}

/**
 * Get slugs of published (non-draft) posts for generateStaticParams
 * ex. [{ path: 'posts/foo', draft: false }] => [{ slug: 'foo' }]
 * @param posts - Posts generated by Velite
 * @returns Route params for each published post
 */
export function getPublishedSlugs(posts: Post[]) {
  return getPublishedPosts(posts).flatMap((post) => {
    const slug = getSlug(post);
    return slug ? [{ slug }] : [];
  });
}

/**
 * Find a published (non-draft) post by its slug
 * @param posts - Posts generated by Velite
 * @param slug - Slug derived from the post path (e.g. 'foo' for 'posts/foo')
 * @returns The matching post, or undefined if it does not exist or is a draft
 */
export function getPublishedPostBySlug(posts: Post[], slug: string) {
  return getPublishedPosts(posts).find((post) => getSlug(post) === slug);
}
